DO $$
declare w text:='summary-test'; r uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); claim jsonb; body jsonb; v bigint;
begin
 perform studio.studio_create_substo_location(w,'Summary','summary-owner');
 insert into studio.studio_records(location_id,id,kind,title,payload) values(w,r,'reference','Source','{"description":"actual evidence","summary":"Human research notes","research":"original evidence"}');
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 begin perform studio.studio_request_library_summary(w,'substo','intruder',r); raise exception 'Cross member accepted'; exception when sqlstate '42501' then null; end;
 insert into studio.studio_devices(id,location_id,app,name,token_hash,request_id,created_by,processing_enabled,desired_config)
 values(d,w,'substo','Test',repeat('a',64),gen_random_uuid(),'summary-owner',true,'{"features":{"text":true}}');
 if studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60}')<>'[]' then raise exception 'Local gate bypass'; end if;
 claim:=studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}');
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 if (select count(*) from studio.studio_jobs where location_id=w)<>1 then raise exception 'Request retry duplicated job'; end if;
 if jsonb_array_length(claim)<>1 then raise exception 'No claim %',claim; end if;
 body:=jsonb_build_object('workerId','test','jobId',claim->0->>'id','leaseToken',claim->0->>'lease_token','result',jsonb_build_object('summary','Short summary','provider','codex','model','native-default'));
 update studio.studio_jobs set attempts=20 where id=(claim->0->>'id')::uuid;
 if studio.studio_library_device_command(repeat('a',64),'substo','fail',body || jsonb_build_object('failure',jsonb_build_object('code','subscription_capacity','message','Waiting','retryable',true,'retryAfterSeconds',300)))<>'"retry_scheduled"' then raise exception 'Capacity waiting exhausted attempts'; end if;
 update studio.studio_jobs set run_after=clock_timestamp()-interval '1 second' where id=(claim->0->>'id')::uuid;
 claim:=studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}');
 body:=body || jsonb_build_object('jobId',claim->0->>'id','leaseToken',claim->0->>'lease_token');
 if studio.studio_library_device_command(repeat('a',64),'substo','complete',jsonb_set(body,'{leaseToken}',to_jsonb(gen_random_uuid())))<>'false' then raise exception 'Lease bypass'; end if;
 update studio.studio_records set version=version+1,payload=payload || '{"description":"edited evidence"}' where id=r and location_id=w;
 if studio.studio_library_device_command(repeat('a',64),'substo','complete',body)<>'true' then raise exception 'Completion failed'; end if;
 if (select payload->>'aiSummary' from studio.studio_records where id=r and location_id=w) is not null then raise exception 'Edited record overwritten'; end if;
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 claim:=studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}');
 body:=body || jsonb_build_object('jobId',claim->0->>'id','leaseToken',claim->0->>'lease_token');
 if studio.studio_library_device_command(repeat('a',64),'substo','complete',body)<>'true' then raise exception 'Fresh completion failed'; end if;
 if (select payload->>'aiSummary' from studio.studio_records where id=r and location_id=w)<>'Short summary' then raise exception 'Summary missing'; end if;
 if (select summary from studio.studio_records where id=r and location_id=w)<>'Human research notes' or (select payload->>'research' from studio.studio_records where id=r and location_id=w)<>'original evidence' then raise exception 'Human evidence overwritten'; end if;
 if studio.studio_library_device_command(repeat('a',64),'substo','complete',body)<>'false' then raise exception 'Completion replay'; end if;
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 update studio.studio_records set version=version+1,payload=payload || '{"importRequestKeys":["retry"]}'::jsonb where location_id=w and id=r;
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 if studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}')<>'[]' then raise exception 'Metadata retry regenerated summary'; end if;
 update studio.studio_records set version=version+1,payload=payload || '{"description":"new evidence for expiry test"}'::jsonb where location_id=w and id=r;
 perform studio.studio_request_library_summary(w,'substo','summary-owner',r);
 claim:=studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}');
 body:=body || jsonb_build_object('jobId',claim->0->>'id','leaseToken',claim->0->>'lease_token');
 update studio.studio_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id=(claim->0->>'id')::uuid;
 if studio.studio_library_device_command(repeat('a',64),'substo','complete',body)<>'false' then raise exception 'Expired completion accepted'; end if;
 perform studio.studio_claim_jobs('hosted-expiry',10,60);
 if studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}')<>'[]' then raise exception 'Uncertain execution replayed'; end if;
 begin perform studio.studio_library_device_command(repeat('a',64),'estio','complete',body); raise exception 'Cross realm accepted'; exception when sqlstate '42501' then null; end;
 update studio.studio_devices set revoked_at=now() where id=d;
 begin perform studio.studio_library_device_command(repeat('a',64),'substo','complete',body); raise exception 'Revoked accepted'; exception when sqlstate '42501' then null; end;
 update studio.studio_devices set revoked_at=null where id=d;
 update public."UserLocationRole" set role='MEMBER' where "locationId"=w and "userId"='substo:summary-owner';
 begin perform studio.studio_library_device_command(repeat('a',64),'substo','complete',body); raise exception 'Removed manager authority accepted'; exception when sqlstate '42501' then null; end;
 insert into studio.studio_records(location_id,kind,title,payload) values(w,'reference','Empty','{"summary":"Human-only notes"}') returning id into r;
 perform public.test_member(w,'summary-owner','admin');
 if studio.studio_request_library_summary(w,'substo','summary-owner',r)->>'summaryStatus'<>'no_evidence' then raise exception 'Missing evidence not reported'; end if;
 if exists(select 1 from studio.studio_library_summary_requests where location_id=w and record_id=r) then raise exception 'Phantom empty summary request'; end if;
 if studio.studio_library_device_command(repeat('a',64),'substo','claim','{"workerId":"test","limit":1,"leaseSeconds":60,"summaryReady":true}')<>'[]' then raise exception 'Empty evidence claimed'; end if;
 perform studio.studio_create_substo_location('summary-other','Other','other-owner');
 insert into studio.studio_devices(location_id,app,name,token_hash,request_id,created_by) values('summary-other','substo','Other',repeat('b',64),gen_random_uuid(),'other-owner');
 begin perform studio.studio_library_device_command(repeat('b',64),'substo','complete',body); raise exception 'Cross tenant completion accepted'; exception when sqlstate '42501' then null; end;
end $$;
